import boto3

def get_text(block, blocks_index):
    text = ''
    if 'Relationships' in block:
        for relationship in block['Relationships']:
            if relationship['Type'] == 'CHILD':
                for child_id in relationship['Ids']:
                    child = blocks_index[child_id]
                    if child['BlockType'] == 'WORD':
                        text += child['Text'] + ' '
                    if child['BlockType'] == 'SELECTION_ELEMENT':
                        if child['SelectionStatus'] == 'SELECTED':
                            text += 'X '
                        else:
                            text += '□ '
    return text.strip()

def extract_key_value_pairs(file_path):
    with open(file_path, 'rb') as file:
        document_bytes = file.read()

    client = boto3.client('textract')

    response = client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['FORMS']
    )

    blocks = response['Blocks']

    blocks_index = {}
    for block in blocks:
        blocks_index[block['Id']] = block

    key_value_set = {}

    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in block['EntityTypes']:
            key = get_text(block, blocks_index)
            value = ''
            if 'Relationships' in block:
                for relationship in block['Relationships']:
                    if relationship['Type'] == 'VALUE':
                        for value_id in relationship['Ids']:
                            value_block = blocks_index[value_id]
                            value = get_text(value_block, blocks_index)
                            break
                    if value:
                        break
            key_value_set[key] = value

    return key_value_set
